select 'mod-trouver-ses-premiers-clients', 1, 'Chapitre 1', 'Introduction', 2, '[{"temps":"0:00","texte":"Alors, le piège de l''attente."},{"temps":"0:05","texte":"Pourquoi il ne faut pas attendre d''être prêt avant de se lancer ?"},{"temps":"0:08","texte":"Parce qu''en vrai, il n''y a jamais de bon moment."},{"temps":"0:11","texte":"Il n''y a pas de bon moment pour dire : « Voilà, tout est prêt. » Si vous cherchez à être prêt, vous aurez toujours une bonne raison de repousser."},{"temps":"0:20","texte":"Vous aurez toujours une bonne raison de repousser."},{"temps":"0:24","texte":"N''attendez pas d''avoir le logo parfait :"},{"temps":"0:27","texte":"ce n''est pas le logo qui va vous amener des premières ventes."},{"temps":"0:30","texte":"N''attendez pas d''avoir le site internet parfait ou bien la page des réseaux sociaux parfaite avec le maximum d''abonnés. Vous dites : « Voilà,"},{"temps":"0:39","texte":"j''attends quand j''aurai 1 000 abonnés, j''aurai 5 000 abonnés ; là, à ce moment, je vais commencer à faire mes ventes. » Non. Non."},{"temps":"0:50","texte":"Ça, ça sera une grave erreur."},{"temps":"0:55","texte":"Si vous attendez, si vous attendez d''être prêt, vous n''allez jamais démarrer. Vous n''allez jamais démarrer."},{"temps":"1:01","texte":"Il n''y a pas de bon moment. Le bon moment, c''est maintenant."},{"temps":"1:04","texte":"Commencez, et puis vous allez le rendre parfait dans la suite."},{"temps":"1:09","texte":"Il n''y a aucune entreprise qui a démarré et puis tout était parfait, parfait, parfait, parfait. À partir du moment où vous avez votre produit,"},{"temps":"1:16","texte":"à partir du moment où il fonctionne, votre produit ou votre service fonctionne, c''est déjà suffisant pour démarrer votre business, pour démarrer votre entreprise. Vous n''avez pas de logo ?"},{"temps":"1:26","texte":"Peu importe, vous démarrez. C''est maintenant que vous allez créer votre page sur les réseaux sociaux ? Peu importe, vous démarrez."},{"temps":"1:32","texte":"Vous n''avez pas le site internet qui va donner l''impression que tout est bien ? Peu importe, vous démarrez."},{"temps":"1:39","texte":"Mais le meilleur moment, c''est maintenant. N''attendez pas la perfection."},{"temps":"1:44","texte":"Cherchez juste à poser l''action, et puis les choses vont couler de source."}]'::jsonb, 'srt', 'ENT_M04_C01_Introduction.srt', now(),
  v.id, 'construire-une-offre-simple-et-commencer-a-vendre-ch02-1e9f3f', 'hls', 110, 'ENT_M04_C01_Introduction.mp4', 19164675, now(), true from v
