select 'mod-trouver-ses-premiers-clients', 2, 'Chapitre 2', 'Définitions', 3, '[{"temps":"0:01","texte":"Alors, dans la suite du module, on va utiliser certains termes, comme une offre. Une offre, c''est quoi ? Généralement, on entend ça beaucoup quand on entend parler de marketing et de communication. Une offre,"},{"temps":"0:13","texte":"tout simplement, c''est ce que vous allez proposer au marché : c''est votre produit, c''est votre service, c''est un prix, et puis c''est comment faire pour l''avoir."},{"temps":"0:21","texte":"C''est ça, une offre. Donc, par exemple, une offre de téléphone, c''est un iPhone 15 Pro à 500 000 ; pour l''avoir, contactez tel numéro."},{"temps":"0:31","texte":"Simplement. Ça, c''est une offre."},{"temps":"0:33","texte":"Donc, un produit, un prix, comment faire pour l''avoir :"},{"temps":"0:37","texte":"ça, ça correspond à une offre. Ensuite, il y a ce qu''on appelle les offres de lancement. Donc, une offre de lancement, c''est l''offre avec laquelle vous rentrez sur le marché."},{"temps":"0:46","texte":"C''est la première offre que vous faites pour rapidement déclencher des ventes, pour pousser les gens à acheter immédiatement."},{"temps":"0:54","texte":"On parle d''offres de lancement ou d''offres irrésistibles :"},{"temps":"0:58","texte":"pour pousser les gens à acheter maintenant et pas plus tard, pour pousser les gens à vous choisir, à décider d''acheter chez vous et pas chez quelqu''un d''autre."},{"temps":"1:05","texte":"Donc, une offre de lancement, c''est ce qui va vous permettre de rentrer sur le marché et de commencer à faire vos premières ventes."},{"temps":"1:11","texte":"Ensuite, il y a les termes comme un prospect."},{"temps":"1:13","texte":"Un prospect, ce sont les personnes qui sont susceptibles d''acheter votre produit ou votre service."},{"temps":"1:20","texte":"Il y a le grand marché, il y a tout le monde, il y a toute la terre entière, mais parmi toute la terre entière, il y a des gens qui sont susceptibles d''acheter votre produit,"},{"temps":"1:29","texte":"qui remplissent plus les conditions de personnes qui ont besoin de votre produit. Oui, peut-être que votre produit peut intéresser tout le monde, mais tout le monde ne va pas s''intéresser à ça."},{"temps":"1:40","texte":"Donc, il y a des gens qui vont être sensibles à votre produit ou votre service et qui vont même manifester de l''intérêt pour votre produit."},{"temps":"1:48","texte":"Ceux-là, on va les appeler les prospects."},{"temps":"1:51","texte":"Donc, tous ceux qui deviennent clients sont avant tout des prospects :"},{"temps":"1:54","texte":"c''est une partie des prospects qui devient client."},{"temps":"1:58","texte":"Ensuite, il y a ce qu''on appelle le canal de vente."},{"temps":"2:00","texte":"Donc, le canal de vente, c''est le moyen par lequel vous allez passer pour pouvoir atteindre votre cible, avoir des prospects qui seront finalement transformés en clients. Donc, il y a différents types de canaux."},{"temps":"2:14","texte":"Il y a les canaux digitaux qu''on connaît : les réseaux sociaux, WhatsApp, Facebook, Instagram, TikTok ; ça, ce sont les canaux digitaux."},{"temps":"2:21","texte":"Il y a les canaux traditionnels : la télévision, la radio, l''affichage, les panneaux publicitaires dans la ville ; ça aussi, ce sont des canaux."},{"temps":"2:28","texte":"Il y a le bouche-à-oreille, donc je parle à un ami :"},{"temps":"2:31","texte":"ça, c''est un canal. Donc, vous avez différents types de canaux que vous pouvez utiliser pour faire connaître votre offre de lancement, pour que ça puisse atteindre la bonne cible,"},{"temps":"2:42","texte":"qui deviendra finalement un client. Donc, on a une offre, on a une offre de lancement, on a des prospects qu''on cherche à atteindre, on utilise un canal pour pouvoir les atteindre et,"},{"temps":"2:52","texte":"normalement, si tout est bien, à la fin, ils deviendront clients."},{"temps":"2:55","texte":"Et entre autres canaux, il y a le bouche-à-oreille, qui est le premier canal par lequel les ventes se font."},{"temps":"3:05","texte":"C''est un peu le canal par excellence, c''est juste que, par moments, il est un peu aléatoire."},{"temps":"3:09","texte":"Donc, on a deux, trois techniques pour le faire tourner en notre faveur."},{"temps":"3:14","texte":"Donc, voici un peu pour le vocabulaire que vous devez garder en tête, qui vous aidera à mieux comprendre tout ce qu''on va faire par la suite."}]'::jsonb, 'srt', 'ENT_M04_C02_Definitions.srt', now(),
  v.id, 'construire-une-offre-simple-et-commencer-a-vendre-ch03-460291', 'hls', 203, 'ENT_M04_C02_Definitions.mp4', 27025392, now(), true from v
