-- ENT_M05 · Convertir les conversations en vente
update modules set slug = 'convertir-les-conversations-en-vente',
  numero = 5,
  titre = 'Convertir les conversations en vente',
  programme = 'entrepreneurs',
  thematique_id = 'th-ent-vente',
  formateur_id = 'for-soboro',
  promesse = 'Menez vos conversations commerciales jusqu’à la vente : écouter, proposer, répondre aux objections et relancer sans harceler.',
  pourquoi = 'Des prospects vous écrivent, mais les échanges s’arrêtent avant l’achat. Vendre trop vite, réciter le même discours ou relancer tous les jours fait fuir. Ce module vous donne des scripts de conversation qui convertissent, une manière d’accueillir les objections comme des signaux d’achat, et un plan de relance en trois étapes.',
  pour_qui = array['Vous recevez des demandes, mais peu se transforment en ventes.', 'Vous ne savez pas quoi répondre à « c’est cher ».', 'Vous hésitez entre relancer et laisser tomber.']::text[],
  prerequis = 'Aucun prérequis particulier. Le module prolonge « Comment construire une offre simple et commencer à vendre ».',
  acquis = array['écouter et reformuler le besoin avant de parler de prix ;', 'mener une conversation de vente avec un script adapté à chaque prospect ;', 'conclure avec des questions fermées ;', 'faire émerger et traiter les objections, dont « c’est cher », sans baisser vos prix ;', 'relancer en trois étapes sans donner le sentiment de harceler.']::text[],
  livrable = 'Vos scripts de conversation, vos réponses aux objections les plus fréquentes et votre plan de relance en trois étapes.',
  faq = '[{"question":"Les scripts fonctionnent-ils sur WhatsApp et en messagerie ?","reponse":"Oui. Les scripts portent sur la conduite de la conversation : ils s’appliquent aussi bien par message que de vive voix, en les adaptant à chaque prospect."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb,
  points_forts = array[]::text[],
  duree_minutes = 47,
  seo_mot_cle_principal = 'conversation de vente',
  seo_title = 'Convertir les conversations en vente',
  seo_meta_description = 'Scripts, objections et relances : transformez vos conversations commerciales en ventes, avec Lyle Soboro. Module vidéo E-Masterclass Big Five.',
  statut = 'disponible',
  publie_le = '2026-10-20',
  pret_le = '2026-10-20T15:02:20.294Z',
  maj_le = now()
where id = 'mod-vendre-sans-site-web-whatsapp-business';
with v as (
  insert into videos (cle, nom, nom_fichier, taille_octets, duree_secondes, format)
  values ('convertir-les-conversations-en-vente-ch01-b57ed2', 'Convertir les conversations en vente · Introduction · Présentation du module', 'ENT_M05_C00_Intro.mp4', 38482743, 116, 'hls')
  returning id
)
insert into chapitres (module_id, position, libelle, titre, duree_minutes, script, script_format, script_nom_fichier, script_importe_le,
