insert into chapitres (module_id, position, libelle, titre, duree_minutes, script, script_format, script_nom_fichier, script_importe_le,
  video_id, video_cle, video_format, video_duree_secondes, video_nom_fichier, video_taille_octets, video_importee_le, sous_titres)
select 'mod-vendre-sans-site-web-whatsapp-business', 4, 'Chapitre 4', 'Objections et relances : conclure sans harceler', 19, '[{"temps":"0:03","texte":"Une objection, ce n''est pas un refus :"},{"temps":"0:05","texte":"c''est une demande d''information pour être rassuré."},{"temps":"0:09","texte":"Vous devez garder ça absolument en tête."},{"temps":"0:12","texte":"Vous devez vous mettre dans votre tête que quand on met une objection, ce n''est pas pour faire palabre. Ce n''est pas pour vous décourager, ce n''est pas pour fuir, ce n''est pas pour tout ça."},{"temps":"0:23","texte":"C''est un processus normal. Vous-même, quand vous partez acheter des choses, vous émettez des objections. C''est normal."},{"temps":"0:29","texte":"Vous allez dire au vendeur que c''est cher. Quand c''est une grande décision, vous allez dire que vous avez besoin de parler, de consulter votre conjoint pour pouvoir décider d''acheter."},{"temps":"0:38","texte":"Ce n''est pas un refus. C''est une demande d''information pour être rassuré."},{"temps":"0:42","texte":"Et puis, on va conclure la vente. Ce qu''il ne faut pas faire, c''est baisser son prix dès la première hésitation."},{"temps":"0:52","texte":"Ça aussi, c''est une erreur."},{"temps":"0:54","texte":"Dès que le client vous dit que c''est cher, votre premier réflexe, c''est de baisser le prix. Si vous le faites, ça veut dire que vous-même, vous pensez que votre prix, là, c''est cher."},{"temps":"1:06","texte":"C''est parce que vous pensez que votre prix est cher, élevé, et il n''est pas basé sur une réflexion profonde."},{"temps":"1:19","texte":"Dès qu''on va vous dire que c''est cher, vous allez chercher à baisser votre prix."},{"temps":"1:22","texte":"C''est une mauvaise stratégie. Déjà, un : en termes de coût, ce n''est pas bon de baisser son prix, parce que vous allez faire quoi ?"},{"temps":"1:29","texte":"Vous allez baisser indéfiniment. Deuxièmement, ça donne un mauvais signal au client, parce qu''il va se dire que la première fois qu''on lui a donné le prix, ce n''était pas un bon prix."},{"temps":"1:38","texte":"Donc, il ne faut pas baisser le prix dès la première hésitation."},{"temps":"1:43","texte":"Ce qu''il ne faut pas faire, c''est argumenter agressivement pour avoir raison."},{"temps":"1:49","texte":"C''est la vente, ce n''est pas un débat contradictoire. Vous n''êtes pas en train de chercher à avoir raison."},{"temps":"1:56","texte":"Vous êtes en train de chercher à vendre. Donc, quand le client, il vous fait des objections, vous devez plutôt l''écouter et chercher à le rassurer pour l''amener à voir clair dans le truc, au lieu plutôt"},{"temps":"2:12","texte":"d''être en train d''argumenter comme si vous étiez en palabre. Donc, supplier ou faire culpabiliser le prospect, c''est mauvais. Disparaître sans laisser de prochaine étape :"},{"temps":"2:27","texte":"c''est ce que je disais. Vous finissez de faire la discussion et, à la fin, il n''y a pas…"},{"temps":"2:32","texte":"qu''est-ce qu''on fait ?"},{"temps":"2:34","texte":"Vous avez laissé le prospect comme ça."},{"temps":"2:35","texte":"Et lui aussi, comme l''argent ne suffit jamais et qu''il a la possibilité de se défiler, il va en profiter pour se défiler."},{"temps":"2:43","texte":"Ce qu''il ne faut pas faire, c''est prendre l''objection comme une attaque personnelle. Il y en a, des entrepreneurs qui sont très attachés à leur projet, surtout ceux qui fabriquent leurs produits."},{"temps":"3:00","texte":"Donc, automatiquement, quand on leur pose des questions, quand on leur pose des questions sur le prix ou même sur l''efficacité du produit, ils prennent ça comme une attaque personnelle,"},{"temps":"3:09","texte":"comme si on venait remettre en cause qui ils sont."},{"temps":"3:14","texte":"Vous ne devez pas faire cette erreur-là. Déjà, détachez-vous émotionnellement de votre produit. Mais c''est normal que les gens vous posent des questions"},{"temps":"3:22","texte":"ou vous remettent en cause, parce qu''il va quand même prendre son argent, qu''il a durement gagné après des heures et des heures de travail, pour venir vous le donner. Donc, il a besoin de s''assurer"},{"temps":"3:30","texte":"que ce qu''il est en train de faire, ce n''est pas une mauvaise chose, un mauvais investissement. Ce qu''il faut plutôt faire :"},{"temps":"3:38","texte":"accueillir l''objection sans se justifier."},{"temps":"3:42","texte":"Quand le client vous émet une objection, vous prenez, vous amortissez d''abord."},{"temps":"3:48","texte":"Vous posez des questions pour bien comprendre le frein, ce qui suscite l''objection."},{"temps":"3:57","texte":"Quand il vous dit, par exemple, « C''est cher », au lieu d''être en train de vous débattre — « Non, comment ça, c''est cher ?"},{"temps":"4:03","texte":"Les autres même, ils vendent à tant, moi, je vends à ça » —, ça, vous êtes en train de mal faire."},{"temps":"4:07","texte":"Vous devez d''abord lui demander pourquoi est-ce qu''il pense que c''est cher."},{"temps":"4:14","texte":"Ne serait-ce que cette simple question va faire réaliser au client qu''en fait, il a dit « c''est cher », mais il n''a pas de fondement."},{"temps":"4:23","texte":"C''est cher, mais c''est cher par rapport à quoi ?"},{"temps":"4:27","texte":"Il va considérer que c''est plus cher."},{"temps":"4:30","texte":"Donc, souvent, c''est juste en posant la question que vous allez commencer à mettre le doigt dessus. Il va vous dire que c''est cher, mais en fait, c''est parce que son budget ne lui permet pas d''arriver"},{"temps":"4:39","texte":"à ce niveau-là, parce qu''il avait préparé un budget en tête."},{"temps":"4:43","texte":"Donc, il dit que c''est cher. Et puis, quand vous allez lui demander pourquoi est-ce qu''il pense que c''est cher, c''est là qu''il va te dire : « En fait, moi, j''avais prévu 10 000 francs pour ça."},{"temps":"4:51","texte":"Donc, 30 000 francs, c''est trop pour moi. » Là, on commence à comprendre."},{"temps":"4:56","texte":"Donc, ce n''est pas tant qu''il considère que le produit est cher, c''est juste que sa capacité financière ne lui permet pas d''aller jusque-là."},{"temps":"5:04","texte":"Oui. Et quand on a compris le fond de l''objection, on peut maintenant utiliser des arguments pour obtenir gain de cause. Donc, il y a plusieurs options."},{"temps":"5:15","texte":"Par exemple, dans le cas du « c''est cher », s''il considère que c''est cher, c''est parce qu''il n''a pas le budget. Ce que nous, on va faire, c''est chercher à rehausser la valeur perçue qu''il a du produit."},{"temps":"5:26","texte":"C''est de lui montrer : « Je comprends parfaitement que vous n''avez pas défini ce budget-là, mais le produit-là, vraiment, il va vous apporter beaucoup de bien. Le mariage où vous avez prévu d''aller,"},{"temps":"5:37","texte":"je sais que vous appréciez énormément le couple qui se marie."},{"temps":"5:42","texte":"Donc, vous voulez les honorer. Donc, il vous faut quelque chose de qualité."},{"temps":"5:48","texte":"J''aurais pu vous proposer quelque chose, peut-être, qui est de moins bonne qualité, mais vous n''allez pas être satisfait."},{"temps":"5:53","texte":"Pour ce que vous m''avez dit que vous recherchez pour le mariage et ce que ça représente pour vous, vraiment, la meilleure chose à faire, ce serait de prendre ça, parce que c''est le bon produit"},{"temps":"6:03","texte":"qui correspond. » À ce moment-là, on n''est pas en train de chercher à baisser le prix, mais on est plutôt en train de chercher à augmenter la valeur perçue du produit."},{"temps":"6:15","texte":"Et puis, on va maintenant peut-être lui dire :"},{"temps":"6:17","texte":"« Allez, il y a deux semaines, il y a quelqu''un qui a acheté ça pour un mariage, il a envoyé sa photo : regardez comment est-ce qu''il était beau, il représentait, c''était magnifique. » Donc là,"},{"temps":"6:26","texte":"on lui donne encore des preuves pour augmenter sa valeur perçue."},{"temps":"6:30","texte":"Et si, malgré tout ça, il n''a vraiment pas la capacité d''augmenter son budget, on peut maintenant chercher à avoir des alternatives, comme un paiement fractionné. On dit : « Bon, vu que le mariage,"},{"temps":"6:46","texte":"c''est dans quelques jours, peut-être vous pouvez verser 20 000 francs, vous prenez, et puis après, vous nous versez 10 000 francs. » Ou bien on va lui proposer un autre produit qui rentre dans son budget,"},{"temps":"6:58","texte":"ou bien on va trouver un moyen. Mais baisser son prix n''est pas la première solution face à un « c''est cher », face à un « c''est cher »."},{"temps":"7:07","texte":"La première chose à faire, c''est d''abord de comprendre pourquoi il trouve que c''est cher, et ensuite de chercher à augmenter la valeur que le prospect peut avoir du produit. Et souvent,"},{"temps":"7:16","texte":"ils vont vous dire qu''ils n''ont pas prévu ça, mais après les arguments, ils sont prêts à faire des efforts. Je suis sûr que vous avez déjà fait des achats où vous avez prévu de dépenser moins, mais quand vous avez vu"},{"temps":"7:32","texte":"le produit et tout, finalement, vous avez augmenté le budget."},{"temps":"7:35","texte":"Donc, les gens sont prêts à augmenter leur budget s''il y a les bons arguments face à leur objection. Maintenant, si malgré tout ça, si après les arguments d''augmentation de la valeur perçue, si après"},{"temps":"7:55","texte":"l''alternative, au cas où son budget ne peut pas évoluer, il n''y a pas de solution, on laisse la porte ouverte, parce que ça veut dire que ce n''est pas le moment. Donc, on dit : « OK, il n''y a pas de problème."},{"temps":"8:07","texte":"En tout cas, on est là pour une autre occasion, nous sommes là pour un autre contact. » Et tu laisses la porte ouverte pour une prochaine et future vente. Mais on ne se fâche pas,"},{"temps":"8:17","texte":"on ne prend pas ça comme une agression, on ne se sent pas visé."},{"temps":"8:21","texte":"Ce n''est pas une attaque, c''est juste la discussion de la conversation de vente."},{"temps":"8:25","texte":"Et pour pouvoir bien gérer les objections, il y a une méthode."},{"temps":"8:32","texte":"Tout à l''heure, j''expliquais comment est-ce qu''on fait pour gérer les objections, comme les objections des « c''est cher », mais ça suit une méthode. La première chose, c''est écouter."},{"temps":"8:43","texte":"Quand le prospect émet son objection, écouter, écouter pour comprendre l''objection."},{"temps":"8:53","texte":"Ensuite, creuser : poser des questions. Souvent, il a même plusieurs objections :"},{"temps":"8:57","texte":"« C''est cher », « Je vais parler à un ami », « Bon, actuellement, je n''ai pas… », « Qu''est-ce qu''il faut pour que ça marche ? » Donc, au lieu d''être en train de traiter chaque objection individuellement,"},{"temps":"9:07","texte":"vous devez demander à ce qu''il puisse émettre toutes ses objections."},{"temps":"9:11","texte":"Il vous dit « c''est cher » : « OK, d''accord, il n''y a pas de problème."},{"temps":"9:14","texte":"Est-ce que vous avez une autre objection par rapport à ça ? » « Donc, en fait, même quand je regarde là, je ne suis pas très sûr que ça va m''aller. » « Il n''y a pas de problème. Est-ce qu''il y a un autre point bloquant ?"},{"temps":"9:25","texte":"Si tout ça était réglé, qu''est-ce qui va vous pousser à prendre ? » « Bon, c''est vrai que même si ça rentrait dans mon budget et que ça m''allait, il faut que je demande"},{"temps":"9:34","texte":"quand même l''avis de mon épouse avant de décider d''acheter. » Donc là, d''abord, on écoute pour chercher à bien comprendre toutes les objections."},{"temps":"9:44","texte":"Ensuite, on creuse, on pose des questions pour bien comprendre."},{"temps":"9:47","texte":"Si, par exemple, il dit pour son épouse : « Ah, mais si, par exemple, elle était là, c''est quoi qu''elle regarderait pour décider d''acheter ? » Et donc là, je pose des questions, je l''amène lui-même à faire sortir"},{"temps":"9:59","texte":"des choses qui vont m''aider, à la fin, à le convaincre."},{"temps":"10:03","texte":"Il va dire : « Ah bon, ma femme, là, elle, c''est la qualité du tissu."},{"temps":"10:07","texte":"Si le tissu est bon, elle va décider. » Quand il me donne cette information, moi, maintenant, je passe à la phase de le rassurer."},{"temps":"10:15","texte":"Je sais qu''en fait, c''est la qualité du tissu qui peut convaincre."},{"temps":"10:19","texte":"Donc, je dis : « Ah oui, c''est vrai, c''est que votre femme, elle a bon goût, elle connaît les bonnes choses."},{"temps":"10:24","texte":"Mais le boubou que je viens de vous présenter, c''est un bazin riche, c''est telle qualité, c''est telle qualité."},{"temps":"10:32","texte":"Si vous voulez, vous pouvez l''appeler même pour lui demander si tel type de tissu, là, c''est de bonne qualité. Vous allez voir qu''elle va vous confirmer ça, et puis vous allez pouvoir prendre. La dernière fois,"},{"temps":"10:41","texte":"même, il y avait comme ça un monsieur qui est venu, il a pris ; il doutait que sa femme allait accepter, mais quand il est allé à la maison, il m''a appelé : sa femme même a appelé"},{"temps":"10:49","texte":"pour dire qu''elle aimerait bien prendre un autre boubou. » Donc là, maintenant, je fais quoi ? Je le rassure, je donne des preuves, je donne des témoignages qui viennent encore le conforter."},{"temps":"10:59","texte":"Et quand j''ai fini ça, il vient maintenant dire :"},{"temps":"11:02","texte":"« Ah bon, d''accord. » « Donc, est-ce que vous prenez ? » J''essaie de conclure."},{"temps":"11:05","texte":"Maintenant, si à la fin je ne peux pas conclure, parce que peut-être il est encore hésitant, je vais trouver une alternative ou une facilité, et puis,"},{"temps":"11:14","texte":"en fonction de ce qui va être retenu, on va conclure. Donc : écoutez, creusez, rassurez, adaptez si ça coince, et puis fixez le prochain rendez-vous."},{"temps":"11:24","texte":"Derrière un « c''est trop cher » se cache souvent une autre question, un autre frein : il faut poser des questions pour comprendre."},{"temps":"11:33","texte":"Ce que vous devez retenir sur les objections, c''est que quand les gens vous émettent des objections, votre premier réflexe doit être d''écouter, ensuite de creuser, poser des questions,"},{"temps":"11:44","texte":"reformuler, rassurer, et ça va bien se passer."},{"temps":"11:48","texte":"Donc là, on va prendre un exemple."},{"temps":"11:51","texte":"Le client, le prospect, il vous dit : « C''est trop cher. » La réponse qui ne passe pas, c''est : « Bon, il peut te laisser…"},{"temps":"11:58","texte":"il peut baisser à 4 000 si tu veux. » Le prospect va douter : s''il peut baisser si vite, est-ce que le produit, là même, c''est de qualité ? Tu vois ?"},{"temps":"12:07","texte":"Donc, il va commencer à faire : « Bon, il n''y a pas de problème, je réfléchis », et puis il te fait signe après. Là, vous venez de perdre une vente, parce que vous avez mal géré l''objection « c''est trop cher »."},{"temps":"12:17","texte":"Mais si on veut appliquer la méthode, par exemple, ça va faire :"},{"temps":"12:20","texte":"« Ah, je comprends, c''est un vrai budget et c''est normal de réfléchir. Mais c''est le prix qui bloque, ou bien vous hésitez encore sur le modèle ?"},{"temps":"12:32","texte":"Parce que le prix que je viens de vous donner, ça prend en compte la livraison et puis la personnalisation."},{"temps":"12:40","texte":"Regardez : la dernière fois, il y a une dame qui s''appelle Mariam qui a commandé la même chose la semaine passée ; elle est venue faire son retour, elle était très satisfaite. » Et puis maintenant, si malgré ça,"},{"temps":"12:54","texte":"ça coince, on fait : « Sinon, le format deux personnes est à 3 000, il est parfait pour découvrir. Je vous laisse regarder, je vous écris demain pour prendre votre décision, si ça vous va. » Donc, c''est comme ça"},{"temps":"13:05","texte":"que vous devez structurer votre manière de gérer les objections avec l''équipe."},{"temps":"13:13","texte":"Maintenant, quand vous avez mené la conversation, essayé de gérer les objections, et qu''à la fin il n''y a pas eu la vente, donc vous avez laissé la porte ouverte pour pouvoir le relancer,"},{"temps":"13:28","texte":"il y a ce qu''on appelle le follow-up en anglais, sinon c''est les relances commerciales."},{"temps":"13:36","texte":"Là, je vous présente un plan en trois étapes pour relancer un client."},{"temps":"13:47","texte":"Si la discussion s''est terminée, vous pouvez le relancer le lendemain :"},{"temps":"13:56","texte":"un petit rappel léger avec une information utile en plus."},{"temps":"14:02","texte":"Donc, par exemple, vous avez fini de discuter, il a dit d''accord, il va regarder, il vous revient. Le lendemain, vous relancez : « Ah, bonjour monsieur, j''espère que vous avez pu regarder"},{"temps":"14:12","texte":"et tout, mais je voulais juste vous dire qu''actuellement, si vous prenez le produit, on offre tel truc en bonus."},{"temps":"14:20","texte":"Donc, quand vous êtes prêt, n''hésitez pas à me laisser un message pour que vous puissiez finaliser votre commande. » Tu fais ça à J+1."},{"temps":"14:29","texte":"Après, tu attends deux jours encore et, cette fois-ci, tu reviens : « Ah, bonjour monsieur, j''imagine que vous êtes encore en train de réfléchir, que c''est une décision qui est assez importante."},{"temps":"14:39","texte":"Là, je voulais vous partager un retour d''expérience sur le même produit d''une cliente qui a acheté et qui, pour moi, était très satisfaite."},{"temps":"14:48","texte":"Donc, si vous êtes prêt à passer à l''achat, n''hésitez pas à me laisser un message ou à m''appeler. » Et puis, à J+7, donc au bout d''une semaine, vous faites une dernière relance,"},{"temps":"15:01","texte":"vous mettez un limitateur sur la durée pour pouvoir profiter de l''offre, et puis, après ça, vous laissez."},{"temps":"15:08","texte":"On n''est pas obligé de conclure toutes les ventes, mais on fait le maximum pour pouvoir conclure."},{"temps":"15:13","texte":"Si au bout de trois relances le client n''a pas fait signe, vous le laissez, vous vous concentrez sur d''autres prospects beaucoup plus prometteurs."},{"temps":"15:21","texte":"Souvent, les clients ne vont pas être chauds actuellement parce que l''argent ne suffit pas, et puis il va revenir des mois plus tard pour vous dire : « J''avais vu votre truc dernièrement,"},{"temps":"15:31","texte":"ça m''avait intéressé, mais je ne l''ai pas pris."},{"temps":"15:34","texte":"Est-ce que je peux toujours profiter de l''offre ? » J''ai une boutique de produits électroniques, téléphones et autres, et j''avais fait une offre sur un réseau où c''était un package d''un MacBook Neo plus un iPhone 16."},{"temps":"15:53","texte":"Je crois que j''avais facturé à 1 million. Donc, j''ai fait la com, et il y a des personnes qui m''ont écrit, qui m''ont posé des questions, et j''ai suivi la même structure : écouter, poser des questions,"},{"temps":"16:07","texte":"rassurer, donner les détails et tout ça."},{"temps":"16:09","texte":"Et malgré tout, à la fin, quelqu''un a dit :"},{"temps":"16:11","texte":"« Il n''y a pas de problème, j''ai bien compris, je vais m''organiser et puis je vous reviens. » Il n''y a pas de problème. J''ai fait un peu de relance ; une semaine après, il n''y a plus de résultat, j''ai laissé."},{"temps":"16:21","texte":"C''est un mois plus tard que le prospect est venu : « Ah, bonjour, on avait discuté la dernière fois et tout ça, j''étais intéressé par tel…. Est-ce que l''offre est toujours disponible ?"},{"temps":"16:32","texte":"Est-ce que je peux la prendre ? » C''est comme ça que je conclus la vente, et puis j''avance. Donc, ce n''est pas parce qu''on fait une discussion aujourd''hui, on va jusqu''au bout, on essaie de"},{"temps":"16:43","texte":"gérer les objections, et qu''on n''a pas pu conclure aujourd''hui que ça veut dire que la vente, elle est morte."},{"temps":"16:50","texte":"Non, non, non : le truc, c''est de remplir son pipe."},{"temps":"16:53","texte":"Plus j''ai de prospects avec qui je fais des discussions et que je vais jusqu''au bout, à un moment donné, il y en a d''autres qui vont se réveiller et qui vont venir."},{"temps":"17:00","texte":"Et puis, mieux, au bout d''un certain temps, on peut encore venir relancer même ces prospects, parce que le truc, c''est de ne pas harceler. Donc, si sur une semaine j''ai relancé trois fois"},{"temps":"17:10","texte":"et que je n''ai pas eu de résultat, moi, je laisse, j''avance sur un autre truc."},{"temps":"17:13","texte":"Mais je peux revenir un mois plus tard, deux mois plus tard pour relancer, et puis on ne sait jamais : comme ça, on peut toujours avoir des clients."},{"temps":"17:19","texte":"Donc, relancer, c''est la méthode, mais ne harcelez pas, et n''ayez pas mal quand, à la fin, ça ne débouche pas."},{"temps":"17:28","texte":"Parce que je le rappelle toujours : ce n''est pas à tout le monde qu''on vend."},{"temps":"17:32","texte":"La majorité des personnes avec qui on discute, même là, ne vont pas devenir clients. Donc, il n''y a pas de problème."},{"temps":"17:38","texte":"Arrêtez de vous mettre martel en tête pour ça."},{"temps":"17:42","texte":"Donc là, ce serait un exercice que vous allez faire, qu''on pourra traiter à la prochaine séance de travaux dirigés, où on va approfondir. Le truc, c''est que, par rapport à votre produit et votre tarif, rédigez"},{"temps":"18:03","texte":"les réponses selon la méthode de gestion des objections pour les trois objections qui s''affichent sur l''écran."},{"temps":"18:12","texte":"Première objection : « C''est trop cher. » Deuxième objection :"},{"temps":"18:14","texte":"« Je vais réfléchir. » Troisième objection :"},{"temps":"18:17","texte":"« Je n''ai pas l''argent en ce moment. » Ne cherchez pas à gagner le débat, ce n''est pas une question d''avoir raison. Ne dites pas : « Non, ce n''est pas cher, non, ce n''est pas cher, non, ce n''est pas ça. » Le truc,"},{"temps":"18:27","texte":"c''est la méthode : on écoute, on pose des questions, on rassure, on s''adapte, et puis on note les actions suivantes."},{"temps":"18:33","texte":"Cherchez à comprendre le prospect, ce qui le freine vraiment, et puis trouvez la manière de gérer ça."},{"temps":"18:41","texte":"Donc, préparez votre réponse pour chacune des objections."},{"temps":"18:44","texte":"Pourquoi je demande de faire ça ? Parce qu''en vrai, ces objections-là vont toujours revenir."},{"temps":"18:53","texte":"Donc, autant être prêt à les gérer plutôt que de laisser et puis d''improviser chaque fois."},{"temps":"18:58","texte":"Parce qu''autant que vous allez chercher à vendre un produit, forcément, vous allez croiser des gens qui vont vous dire « c''est cher »."},{"temps":"19:04","texte":"Forcément."},{"temps":"19:06","texte":"Avec des mots différents, mais ils vont forcément vous dire ça."},{"temps":"19:09","texte":"Donc, à vous de préparer déjà les réponses :"},{"temps":"19:12","texte":"comme ça, quand ça vient vers vous, il n''y a pas de problème."},{"temps":"19:17","texte":"Vous rédigez vos réponses avec la méthode à l''écran, et puis on pourra corriger, affiner ensemble plus tard."}]'::jsonb, 'srt', 'ENT_M05_C04_Objections-et-relances-conclure-sans-harceler.srt', now(),
  v.id, 'convertir-les-conversations-en-vente-ch05-97d189', 'hls', 1168, 'ENT_M05_C04_Objections-et-relances-conclure-sans-harceler.mp4', 129933055, now(), true from v
