  programme = 'entrepreneurs',
  thematique_id = 'th-ent-visibilite',
  formateur_id = 'for-othniel',
  promesse = 'Transformez vos publications en contenus qui suscitent l’intérêt, créent la confiance et génèrent des demandes concrètes.',
  pourquoi = 'Des vues et des likes ne font pas des clients. Un bon contenu n’attire pas tout le monde : il attire les bonnes personnes, avec le bon message, au bon moment. Ce module vous apprend à connaître votre audience, à bâtir une stratégie de contenu, à écrire des posts qui convertissent et à faire de vos abonnés une communauté engagée.',
  pour_qui = array['Vous publiez régulièrement, sans clients à la clé.', 'Vous avez des abonnés, mais peu de réactions ou de ventes.', 'Vous dépendez de la publicité pour obtenir des résultats.']::text[],
  prerequis = 'Aucun prérequis particulier. Une page professionnelle sur un réseau social permet d’appliquer les exercices.',
  acquis = array['définir votre persona et partir de ce que vit votre client ;', 'alterner les piliers de contenu et raconter l’histoire de votre activité ;', 'structurer un post qui convertit ;', 'planifier vos publications avec un calendrier éditorial ;', 'transformer vos abonnés en communauté engagée ;', 'choisir vos indicateurs selon l’objectif et utiliser la publicité à bon escient.']::text[],
  livrable = 'Votre persona, vos piliers de contenu et un calendrier éditorial prêt à publier.',
  faq = '[{"question":"Faut-il faire de la publicité pour appliquer le module ?","reponse":"Non. Le module porte d’abord sur le contenu organique. Un chapitre bonus explique quand la publicité devient utile et comment suivre ses résultats."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb,
  points_forts = array[]::text[],
  duree_minutes = 61,
  seo_mot_cle_principal = 'contenu qui attire les clients',
  seo_title = 'Créer du contenu qui attire les clients',
  seo_meta_description = 'Persona, stratégie de contenu, posts qui convertissent et communauté : attirez des clients avec vos publications, avec Coury Othniel.',
  statut = 'disponible',
  publie_le = '2026-10-20',
  pret_le = '2026-10-20T15:02:20.294Z',
  maj_le = now()
