insert into chapitres (module_id, position, libelle, titre, duree_minutes, script, script_format, script_nom_fichier, script_importe_le,
  video_id, video_cle, video_format, video_duree_secondes, video_nom_fichier, video_taille_octets, video_importee_le, sous_titres)
select 'mod-contenus-qui-attirent-des-clients', 2, 'Chapitre 2', 'C’est quoi un contenu qui attire ?', 24, '[{"temps":"0:00","texte":"Alors, c''est quoi un contenu qui attire ?"},{"temps":"0:06","texte":"Avant d''arriver à donner les définitions et à parler du contenu qui attire, il y a une remarque que nous avons faite : c''est que beaucoup d''entrepreneurs publient régulièrement, mais se posent la même question :"},{"temps":"0:22","texte":"« Pourquoi mes publications obtiennent-elles peu de réactions, peu de messages ou peu de ventes ? » Il faudra savoir que le problème n''est pas forcément la fréquence, parce que, très souvent, le contenu ne répond pas"},{"temps":"0:34","texte":"à une attente précise du client."},{"temps":"0:37","texte":"Un contenu ne doit pas seulement être joli, actif ou viral."},{"temps":"0:42","texte":"Il doit aider à remplir un objectif."},{"temps":"0:46","texte":"Et pour atteindre l''objectif…"},{"temps":"0:49","texte":"bien sûr, l''objectif va dépendre de ce que vous voulez atteindre : vendre, être connu, avoir la confiance, avoir des commandes, faire venir des gens en boutique, et tout ça. Vous avez besoin d''avoir"},{"temps":"1:03","texte":"un objectif bien défini et d''établir une stratégie."},{"temps":"1:07","texte":"Donc, en tant qu''entrepreneur, avant même d''être présent en ligne, vous devez établir ce qu''on appelle, comme je l''ai dit, une stratégie de présence en ligne."},{"temps":"1:16","texte":"Cette stratégie doit être claire, concise et alignée sur vos objectifs. Vous vous rappelez, on a dit tout à l''heure : objectif."},{"temps":"1:25","texte":"Parce que, dans ce monde d''aujourd''hui, tout le monde publie, tout le monde est sur les réseaux sociaux, et tout le monde publie du contenu."},{"temps":"1:32","texte":"Et maintenant même, avec, on va dire, l''avènement de la monétisation qui arrive, il y aura encore plus de personnes qui vont créer et vouloir créer du contenu."},{"temps":"1:42","texte":"Vous avez besoin, vous, à votre niveau, de publier intelligemment, avec stratégie, et surtout avec l''adaptation à votre audience."},{"temps":"1:55","texte":"Et la stratégie pour atteindre vos différents objectifs nécessite que vous fassiez un brainstorming."},{"temps":"2:04","texte":"C''est-à-dire qu''il ne s''agit pas de se lever et de dire : « OK, je vends tel produit, donc je vais aller immédiatement sur Facebook, ou TikTok, ou Snapchat, et commencer à publier pour pouvoir vendre. »"},{"temps":"2:17","texte":"Vous devez faire un brainstorming."},{"temps":"2:18","texte":"Donc ici, on va parler des différents points qui vont nous aider à penser sur le long terme, parce que la différence entre vous et quelqu''un d''autre, par exemple, c''est que vous allez penser sur le long terme,"},{"temps":"2:29","texte":"c''est-à-dire penser à être présent sur une longue durée, et non chercher à vendre des produits çà et là, ou vos services, et après disparaître des radars, disparaître de la présence digitale."},{"temps":"2:41","texte":"Premièrement, vous devez avoir un objectif SMART :"},{"temps":"2:43","texte":"SMART pour spécifique, mesurable, atteignable, réaliste et temporel."},{"temps":"2:49","texte":"Par exemple, ne dites pas : « Je veux des clients. » Vous pouvez dire :"},{"temps":"2:53","texte":"« Je veux générer 10 rendez-vous qualifiés par mois via LinkedIn. » Votre objectif doit être bien défini."},{"temps":"3:01","texte":"C''est celui-là même qui va vous permettre de pouvoir l''atteindre, en mesurant les valeurs pour voir si vous êtes sur la bonne lancée ou pas."},{"temps":"3:09","texte":"Ensuite, vous devez avoir un public cible, encore appelé persona."},{"temps":"3:14","texte":"On va parler de ce point particulier plus en détail."},{"temps":"3:18","texte":"Donc, le public cible, en fait, c''est : qui voulez-vous atteindre ?"},{"temps":"3:23","texte":"Simplement."},{"temps":"3:24","texte":"Ensuite, vous devez avoir des messages clés, c''est-à-dire :"},{"temps":"3:27","texte":"que voulez-vous dire quand vous serez présent ?"},{"temps":"3:30","texte":"Maintenant que vous avez tout ça, vous devez choisir vos canaux de diffusion. Est-ce Facebook, Instagram, WhatsApp, TikTok, LinkedIn, un blog ?"},{"temps":"3:40","texte":"Où est-ce que vous allez diffuser ? Et maintenant, vous devez trouver le format de contenu. Le format de contenu, on en a plusieurs :"},{"temps":"3:46","texte":"on a les articles, on a les textes, on a des images, des vidéos, de l''audio, qui sont disponibles sur les différents réseaux."},{"temps":"3:53","texte":"Et vous devez maintenant avoir un calendrier éditorial."},{"temps":"3:57","texte":"Le calendrier va vous aider à savoir quand publier."},{"temps":"4:01","texte":"Et à la fin, vous devez avoir des KPIs."},{"temps":"4:04","texte":"Les KPIs, ce sont les indicateurs qui vont vous permettre de voir si vous êtes en train d''atteindre votre objectif ou pas."},{"temps":"4:10","texte":"Ce sera pour mesurer le succès."},{"temps":"4:13","texte":"Vous devez comprendre aujourd''hui qu''un contenu sans objectif, c''est comme un journal intime. Vous devez avoir un objectif avant même de venir et de chercher à écrire quelque chose qui va persuader quelqu''un,"},{"temps":"4:26","texte":"ou qui va donner le pouvoir de vendre vos produits ou services."},{"temps":"4:32","texte":"Maintenant, qu''est-ce qu''un contenu qui attire ?"},{"temps":"4:38","texte":"Un contenu attractif, c''est un contenu qui arrête l''attention, qui parle à une personne précise, qui répond à une question, un besoin ou un problème, qui donne"},{"temps":"4:53","texte":"une raison de croire à votre solution, qui invite à faire une action claire."},{"temps":"5:00","texte":"Regardez ce schéma qui est juste à droite :"},{"temps":"5:02","texte":"vous devez d''abord attirer l''attention, ensuite susciter l''intérêt, mettre en confiance et pousser le lecteur à prendre une action."},{"temps":"5:12","texte":"Souvent, quand vous publiez, vous avez l''impression que les gens ne réagissent pas à vos contenus."},{"temps":"5:16","texte":"Si vous parlez trop de vos produits et pas assez des problèmes de votre audience, si vous ne racontez rien d''intéressant ou d''humain, si vous ne publiez pas régulièrement, si vous ne faites pas attention"},{"temps":"5:28","texte":"à la qualité du format de vos contenus, sachez que la cause peut venir de là."},{"temps":"5:33","texte":"En fait, quand vous-même créez du contenu, ou que vous êtes sur les réseaux sociaux, ou même sur internet, mettez-vous toujours à la place de celui qui va lire. Et généralement, c''est ça,"},{"temps":"5:45","texte":"le problème : c''est que, par exemple, les contenus sont rédigés dans l''esprit de celui qui écrit, et non dans l''esprit de celui qui écrit en s''étant mis dans la peau du lecteur."},{"temps":"5:56","texte":"Et ça devient tout de suite la différence entre deux contenus : l''un qui performe et l''autre qui ne performe pas."},{"temps":"6:04","texte":"Un bon contenu doit d''abord parler aux émotions du lecteur, puis au cerveau."},{"temps":"6:09","texte":"Faites la remarque, vous-même qui consommez le contenu quand vous êtes sur les réseaux sociaux : généralement, vous vous êtes arrêté lorsque vous avez remarqué quelque chose qui vous a dit :"},{"temps":"6:19","texte":"« Je veux en savoir plus. » Et quand vous vous mettez dans la peau de celui qui consomme le contenu, vous devez savoir que, lorsque vous produisez le contenu,"},{"temps":"6:28","texte":"vous devez aussi vous mettre dans la peau de l''autre, qui sera en train de lire."},{"temps":"6:32","texte":"Donc, les émotions… les publications qui provoquent une émotion ont généralement tendance à mieux marcher :"},{"temps":"6:38","texte":"les émotions, on va dire, comme l''admiration, la surprise, l''humour, l''indignation. Et donc, vous devez vous poser la question :"},{"temps":"6:46","texte":"« Est-ce que mon post, mon contenu, provoque une émotion ? » Parce que là, on a un contenu qui est attractif, mais il y a aussi un piège qui est derrière."},{"temps":"6:56","texte":"Il faut savoir qu''un contenu attractif n''est pas obligatoirement humoristique, viral ou très sophistiqué. Je pense que vous avez déjà fait la remarque :"},{"temps":"7:08","texte":"des contenus vous ont certainement attiré, mais ce n''étaient pas forcément des contenus viraux, ou à caractère humoristique, ou très sophistiqués."},{"temps":"7:19","texte":"Même un contenu simple suffit à attirer l''attention."},{"temps":"7:23","texte":"Donc, pour un entrepreneur, un contenu est attractif lorsqu''un prospect se reconnaît dans le message et se dit : « Tiens, cette personne comprend mon besoin », ou « Cette offre peut m''aider. »"},{"temps":"7:39","texte":"Donc, en tant qu''entrepreneur, vous devez comprendre et vous mettre dans la peau du fait que les clients achètent des solutions."},{"temps":"7:48","texte":"Alors, quand vous êtes en train de publier le contenu à destination des clients, est-ce que vous êtes la solution de quelqu''un qui vous lit ?"},{"temps":"7:57","texte":"Vous devez vous poser cette question."},{"temps":"8:00","texte":"Et lorsque vous êtes en train de vous poser cette question, vous allez arriver à un certain élément, ou une certaine phase, où il s''agit de prendre les choses"},{"temps":"8:10","texte":"qui ne marchent pas et de les échanger avec les méthodes de celles qui marchent."},{"temps":"8:13","texte":"Par exemple, on prend ce cas-là. Quelqu''un qui poste quelque chose, et il dit :"},{"temps":"8:17","texte":"« Bienvenue chez Élégance de Babi Cosmetics . » Un exemple tout banal."},{"temps":"8:22","texte":"« Nous proposons des soins de qualité à des prix abordables."},{"temps":"8:26","texte":"Contactez-nous. » Et une autre publication, par exemple, on va essayer de la rendre plus attractive. La même publication, si on la modifie un peu, on peut dire,"},{"temps":"8:34","texte":"par exemple : « Votre peau manque d''éclat malgré vos produits ?"},{"temps":"8:38","texte":"Découvrez les trois erreurs qui empêchent votre routine de donner des résultats. » Le premier message présente l''entreprise, mais il ne crée pas de raison immédiate de s''arrêter. Par contre, le deuxième,"},{"temps":"8:50","texte":"qui est « Votre peau manque d''éclat malgré vos produits ?"},{"temps":"8:54","texte":"Découvrez les trois erreurs qui empêchent votre routine de donner des résultats », démarre par une situation que vit le client, et ça crée l''identification, et ça ouvre la porte à une solution."},{"temps":"9:07","texte":"Donc, vous devez avoir ça en esprit :"},{"temps":"9:11","texte":"vous devez commencer par ce que vit le client."},{"temps":"9:14","texte":"Et pour atteindre l''objectif qu''on s''est fixé, vous pouvez être présent en ligne et créer le contenu, mais vous devez jongler entre ce qu''on appelle des piliers de contenu."},{"temps":"9:27","texte":"Donc, les piliers de contenu, en fait, c''est comment, ou bien qu''est-ce que vous allez publier, mais qui ne sera pas répétitif."},{"temps":"9:36","texte":"Un entrepreneur ne doit pas publier uniquement des promotions."},{"temps":"9:41","texte":"C''est-à-dire qu''une page qui ne dit que « Achetez, achetez, promotion, promotion, contactez-nous » va finir par fatiguer rapidement l''audience."},{"temps":"9:51","texte":"Pour garder donc l''attention de votre audience, vous pouvez alterner entre ces quatre piliers de contenu."},{"temps":"9:59","texte":"Le premier, c''est le pilier de contenu éducatif."},{"temps":"10:04","texte":"Donc, quand vous optez pour le pilier de contenu éducatif, vous serez en train d''apporter de la valeur et de vous positionner comme expert. Votre audience vous voit comme quelqu''un d''utile."},{"temps":"10:15","texte":"Ici, on parle de tutoriels, de conseils, d''astuces, de guides, de méthodes ou des erreurs à éviter. Et ça, c''est applicable dans n''importe quel domaine d''activité dans lequel vous êtes,"},{"temps":"10:27","texte":"que vous vendiez vous-même des services ou que vous vendiez des produits physiques ou digitaux."},{"temps":"10:34","texte":"On a aussi un autre type, qui est le pilier divertissant ou engageant."},{"temps":"10:41","texte":"Donc, l''idée ici, c''est de faire interagir l''audience, faire rire ou raconter une situation qui va créer l''émotion, parce que vous savez que l''émotion fait réagir. Donc, des questions, de l''humour,"},{"temps":"10:51","texte":"des défis, ce genre de choses-là, qui feront que, quand quelqu''un vient sur votre page ou vient consommer votre contenu, il a, on va dire, plusieurs choses à consommer. Parce qu''il faudrait savoir que,"},{"temps":"11:02","texte":"lorsque vous êtes sur le réseau, ceux qui consomment votre contenu ou ceux qui voient vos contenus, avec toutes sortes de mises à jour, des algorithmes et tout ça,"},{"temps":"11:10","texte":"ne sont pas forcément les premières personnes qui sont abonnées à votre page ou à vos profils. Donc, il y aura plus de personnes, par exemple, qui vous découvrent. Donc, quand elle va vous découvrir,"},{"temps":"11:19","texte":"comment est-ce que vous voulez qu''elle vous découvre ?"},{"temps":"11:22","texte":"Directement en vendant, ou bien en lui apportant quelque chose d''éducatif, ou bien en posant une question qui reste dans l''esprit de la personne, qui se dit : « Mais tiens,"},{"temps":"11:32","texte":"il faut que je passe voir cette page-là. Qu''est-ce qu''elle propose d''autre ? » En troisième, il y a le contenu, ou bien le pilier inspirant."},{"temps":"11:40","texte":"Donc, ce type de contenu, en fait, renforce la crédibilité et l''attachement."},{"temps":"11:45","texte":"Ici, on va parler de témoignages, de réussites, de partenariats, de coulisses, mais surtout de storytelling."},{"temps":"11:53","texte":"Et là, on va revenir sur ce point particulier du storytelling."},{"temps":"11:57","texte":"Et on peut faire des publications avec le pilier du contenu promotionnel."},{"temps":"12:02","texte":"Donc, ici, il s''agira de générer des ventes et des conversions."},{"temps":"12:07","texte":"Donc, on va parler de lancement, de promo, d''avant-après et de CTA."},{"temps":"12:13","texte":"Le CTA, c''est le call to action, ou bien l''appel à l''action."},{"temps":"12:18","texte":"Règle primordiale, ou règle d''or : lorsque vous vendez des produits et services, si vous faites des publications à caractère promotionnel, ne manquez jamais de laisser un appel à l''action à la fin de votre publication."},{"temps":"12:36","texte":"L''appel à l''action, ça veut dire : qu''est-ce que vous voulez que celui qui vous lit fasse ?"},{"temps":"12:40","texte":"Il vous contacte, il vous appelle, il clique sur le lien, il enregistre la publication — si c''est une vidéo, par exemple, il enregistre la vidéo —, ou bien : qu''est-ce que vous voulez que la personne fasse ?"},{"temps":"12:52","texte":"C''est exactement ce qu''on appelle le call to action."},{"temps":"12:56","texte":"Donc, c''est quelque chose que vous devez aussi savoir."},{"temps":"12:59","texte":"Maintenant, revenons à un point qui est dans le volet inspirant :"},{"temps":"13:06","texte":"le storytelling. On va prendre juste quelques minutes pour parler de ça."},{"temps":"13:12","texte":"Vous devez savoir, par exemple, qu''aujourd''hui, beaucoup d''entrepreneurs ne savent pas raconter l''histoire de leur business pour créer une relation émotionnelle avec les internautes."},{"temps":"13:22","texte":"Et ils ont l''impression que raconter l''histoire de leur entreprise va impliquer une exposition de leur vie privée, vu que la vie de leur business est liée parfois à leur parcours personnel."},{"temps":"13:34","texte":"Et je l''ai rencontré plusieurs fois, ce volet-là, lorsque j''ai eu à gérer des clients, des personnes, ou même quand j''ai eu à travailler pour des entreprises."},{"temps":"13:42","texte":"Mais il est très important."},{"temps":"13:45","texte":"Laissez-moi partager avec vous ce que j''ai appris de mon aîné sur la manière dont vous pouvez facilement raconter l''histoire de votre business sur les réseaux sociaux."},{"temps":"13:53","texte":"Et justement, je vous encourage, après avoir écouté, à expérimenter cette stratégie-là."},{"temps":"13:59","texte":"Donc, quand on parle de storytelling, ça peut être un excellent pilier pour inspirer ceux qui vous suivent et vous rapprocher encore plus de votre public cible."},{"temps":"14:10","texte":"En premier, vous pouvez parler de l''histoire d''origine."},{"temps":"14:13","texte":"Donc, qu''est-ce qu''on veut dire par l''histoire d''origine ? Vous pouvez commencer par partager l''histoire de la création de votre entreprise."},{"temps":"14:20","texte":"Racontez, par exemple, ce qui vous a inspiré à démarrer votre entreprise, les défis que vous avez rencontrés, les motivations qui vous ont poussé à continuer malgré les obstacles."},{"temps":"14:32","texte":"Et ça, comment vous pouvez procéder ?"},{"temps":"14:34","texte":"Par exemple, vous pouvez trouver votre pourquoi, c''est-à-dire : quel est le moment singulier qui a déclenché le parcours de votre marque ?"},{"temps":"14:47","texte":"Est-ce que c''était une épreuve ? C''était un moment d''inspiration ?"},{"temps":"14:51","texte":"Il faut que vous trouviez le pourquoi et que vous l''utilisiez comme une pièce principale de votre histoire d''origine. Et vous devez être authentique."},{"temps":"15:00","texte":"Le public d''aujourd''hui, les personnes qui sont sur les réseaux sociaux, tous ceux qui consomment le contenu, le public est attiré par les marques qui parlent de leur expérience, des perspectives"},{"temps":"15:09","texte":"et des valeurs uniques qui font que telle marque est différente de telle marque, ou telle personne est différente de telle personne. Donc, compte tenu du volume"},{"temps":"15:17","texte":"considérable de contenu qui est diffusé chaque jour sur internet — et vous-même, vous faites la remarque lorsque vous êtes sur les réseaux sociaux —, donc, compte tenu de ce volume-là, vous devez être authentique."},{"temps":"15:31","texte":"Vous pouvez partager l''histoire de votre marque avec ses défauts et tout le reste, parce que ce sont les défis et les imperfections qui peuvent rendre une histoire plus captivante."},{"temps":"15:39","texte":"Et surtout, vous devez montrer le volet humain, parce que, vous-même aussi, quand vous voyez des personnes qui publient ce genre de contenu, faites la remarque : on interagit plus facilement"},{"temps":"15:51","texte":"avec les gens qu''avec une entreprise ou avec d''autres entités professionnelles."},{"temps":"15:55","texte":"Donc, vous pouvez personnaliser votre histoire, par exemple en mettant en lumière les fondateurs de votre marque :"},{"temps":"16:00","texte":"les rêves, le parcours, leur enfance, ce qu''ils ont vécu."},{"temps":"16:04","texte":"Tout ça, ça rapproche les personnes de votre marque. En deuxième, vous pouvez parler du parcours client. Donc, ici, vous pouvez partager des histoires de clients qui ont bénéficié de vos produits ou de vos services."},{"temps":"16:15","texte":"Donc, vous pouvez mettre en avant les témoignages, les expériences positives de vos clients, qui vont illustrer la valeur que vous apportez et susciter l''intérêt des internautes."},{"temps":"16:25","texte":"Pour ça, vous pouvez rassembler des preuves sociales, ou bien encourager vos clients à partager leurs expériences, à l''aide d''enquêtes, de contacts directs par mail,"},{"temps":"16:34","texte":"sur les réseaux sociaux. Et vous devez laisser les clients être des vendeurs. Et c''est tout bénéfique pour vous, d''ailleurs."},{"temps":"16:41","texte":"Et vous pouvez faire ce qu''on appelle « narrer la transformation »."},{"temps":"16:44","texte":"Donc, une chose est de savoir quelque chose, et c''est complètement différent quand cela se déroule sous nos yeux, quand nous-mêmes, nous assistons à cela."},{"temps":"16:55","texte":"Donc, dans la mesure du possible, utilisez des photos, des vidéos, ou bien des éléments visuels qui vont renforcer votre narration, quand vous serez en train de parler de ce volet-là. Troisième :"},{"temps":"17:06","texte":"vous pouvez parler de l''histoire de la valeur, qui est issue de la vision."},{"temps":"17:11","texte":"Généralement, une entreprise, on va dire, a une mission et une vision."},{"temps":"17:15","texte":"Sur le long terme, c''est ce qui définit l''entreprise."},{"temps":"17:18","texte":"Vous pouvez expliquer comment la vision de votre entreprise s''est traduite dans les valeurs que vous défendez et dans les actions que vous entreprenez."},{"temps":"17:26","texte":"Très important aussi : vous pouvez montrer comment votre entreprise contribue à résoudre un problème ou bien à améliorer la vie des gens."},{"temps":"17:34","texte":"Si, par exemple — on va prendre un cas —, vous reversez 10 % à une association ou bien à une œuvre, et tout ça, et tout cela contribue à atteindre votre vision."},{"temps":"17:47","texte":"Donc, vous devez définir votre pourquoi."},{"temps":"17:50","texte":"Vous devez articuler clairement les valeurs fondamentales et la vision de votre marque, et vous pouvez partager, par exemple, un objectif, ou démontrer la différence que votre marque fait dans le monde."},{"temps":"18:02","texte":"C''est très important, et ça permet de se différencier, lorsque vous arrivez à montrer que vous n''êtes pas là que pour vendre, par exemple. C''est vrai,"},{"temps":"18:09","texte":"on est tous sur les réseaux sociaux principalement pour avoir des chiffres et tout, mais aborder cet autre aspect-là rend votre témoignage, ou bien, on va dire, votre entreprise, encore plus humaine."},{"temps":"18:23","texte":"Vous pouvez aussi parler de l''histoire des défis et des triomphes, c''est-à-dire les histoires de défis : vos défis, vos triomphes, tout ce que vous avez expérimenté."},{"temps":"18:36","texte":"Vous pouvez aussi parler de vos coulisses. Donc, les coulisses, très important :"},{"temps":"18:40","texte":"si vous vendez des produits, par exemple, il n''y a pas de meilleur moyen d''instaurer la confiance que la transparence, c''est-à-dire en donnant à votre public un aperçu derrière le rideau. Donc, derrière les coulisses :"},{"temps":"18:50","texte":"« Voici comment ça fonctionne. Voici ce qu''on fait."},{"temps":"18:53","texte":"Voici à quel moment on se réveille. Voici comment on envoie les produits."},{"temps":"18:56","texte":"Voici, voici, voici. » Donc, tout ça permet de pouvoir encore être transparent et impliquer votre audience, parce qu''ils se sentent encore plus concernés par votre, on va dire,"},{"temps":"19:05","texte":"votre chaîne et votre processus pour pouvoir les satisfaire."},{"temps":"19:09","texte":"Parce qu''un client qui regarde tout ce que vous faites, il se sent au cœur de l''action ; il se sent comme si c''était lui, on va dire, qui gérait aussi la page avec vous."},{"temps":"19:19","texte":"Donc ça, ce sont quelques éléments que vous pouvez utiliser pour, on va dire, développer votre storytelling en parlant du pilier inspirant, lorsque vous serez sur ce pilier de contenu."},{"temps":"19:32","texte":"Bien. Maintenant, avant d''arriver à la prochaine étape, à la prochaine slide, il y a aussi le fait qu''on doit parler des algorithmes."},{"temps":"19:41","texte":"Quand nous sommes sur les réseaux sociaux, on dit « l''algorithme » sur les réseaux sociaux, Facebook, TikTok, Instagram et tout ça : en fait, c''est le système automatisé"},{"temps":"19:50","texte":"qui décide quels contenus vont être montrés à chaque utilisateur."},{"temps":"19:55","texte":"Donc, ce processus-là repose sur une série de critères très spécifiques, et il diffère d''une plateforme à l''autre."},{"temps":"20:02","texte":"Ce qui est intéressant, ce qu''il faut retenir, c''est que tous les algorithmes partagent un objectif commun : celui d''améliorer l''expérience utilisateur, donc de celui qui est sur les réseaux sociaux,"},{"temps":"20:15","texte":"en lui proposant des contenus susceptibles de l''intéresser et de maintenir son attention. On va dire que c''est de faire en sorte que celui"},{"temps":"20:22","texte":"qui est en train de consommer le contenu reste le plus longtemps sur la plateforme."},{"temps":"20:28","texte":"Donc, l''algorithme teste votre contenu. Quand vous publiez, il va montrer votre contenu à un petit groupe d''abonnés ou bien d''utilisateurs."},{"temps":"20:36","texte":"Ensuite, l''algorithme va observer les réactions :"},{"temps":"20:39","texte":"est-ce que les gens likent, commentent, partagent, ou bien regardent la vidéo jusqu''à la fin ?"},{"temps":"20:44","texte":"Ensuite, l''algorithme va noter votre post."},{"temps":"20:46","texte":"S''il y a beaucoup d''interactions, il le considère comme intéressant."},{"temps":"20:51","texte":"C''est normal : dans la réalité, même dans la vie, c''est quelque chose d''intéressant quand beaucoup de personnes s''intéressent à regarder, à partager."},{"temps":"20:57","texte":"Donc, c''est ce que l''algorithme regarde, et il va l''élargir."},{"temps":"21:00","texte":"C''est-à-dire que si le contenu plaît, dans les minutes qui suivent, il va le montrer à plus de gens, même à ceux qui ne vous suivent pas."},{"temps":"21:07","texte":"Donc, plus les gens réagissent rapidement, on va dire, après la publication, plus l''algorithme va vous donner de la visibilité."},{"temps":"21:15","texte":"On va parler ici des commentaires, des partages, du temps passé sur une vidéo ou bien sur un post, et des enregistrements : par exemple, sur Instagram, sur TikTok, on peut enregistrer des publications."},{"temps":"21:32","texte":"Regardons maintenant cet exemple-là."},{"temps":"21:34","texte":"On a parlé tout à l''heure des quatre piliers que vous pouvez utiliser."},{"temps":"21:39","texte":"Prenons ce cas : on a un même business, on a quatre contenus. C''est l''exemple d''une coiffeuse."},{"temps":"21:45","texte":"Donc, par exemple, comme type de contenu pour le premier pilier, qui est le pilier éducatif, on peut donner comme contenu, ou bien comme post, par exemple : « Comment protéger vos cheveux après une pose ? »"},{"temps":"21:58","texte":"Et ça peut être accompagné d''une vidéo, ou bien d''un carrousel, ou bien d''une image qui décrit tout ça. Donc là, on éduque le public, par exemple."},{"temps":"22:09","texte":"On a parlé aussi d''engagement. On peut dire, par exemple : « Quelle coiffure vous tente cette semaine ? », et on met deux coiffures."},{"temps":"22:15","texte":"On va dire, par exemple, des dreadlocks ou bien un curly : A et B."},{"temps":"22:21","texte":"Et les internautes, ou bien les followers, doivent répondre A ou bien B."},{"temps":"22:26","texte":"Et là, maintenant, quand les internautes seront en train de répondre, vous devez être en train de répondre aux commentaires."},{"temps":"22:35","texte":"Par exemple, si quelqu''un dit A, il ne s''agit pas de dire : « Merci pour votre réponse », et de partir. Non. Parce que ce pilier-là aussi, le pilier engageant…"},{"temps":"22:43","texte":"l''un des avantages, et quelque chose à prendre en considération, c''est que, quand vous êtes en train de générer des publications à caractère engageant, vous devez aussi vous engager avec la cible,"},{"temps":"22:53","texte":"avec les internautes, avec ceux qui répondent, de sorte à ce que la portée de la publication soit plus ouverte."},{"temps":"23:00","texte":"On a parlé aussi des contenus inspirants. On peut dire, par exemple, avant-après, et on va raconter l''histoire d''une cliente."},{"temps":"23:06","texte":"Avant, elle avait, par exemple, des cheveux courts ou bien des cheveux noirs. Elle a teint ça, par exemple, en blanc ou bien en marron. Et puis, on raconte son histoire :"},{"temps":"23:15","texte":"« Voici ce qu''elle est devenue. Voici comment elle se sent."},{"temps":"23:18","texte":"Elle a pris confiance en elle », et tout ça."},{"temps":"23:21","texte":"Ça fait qu''on se rapproche plus de la publication, et qui dit publication dit de l''entreprise ou de la marque. Et on peut vendre maintenant, par exemple,"},{"temps":"23:30","texte":"un pack spécial de trois perruques à 15 000 francs, uniquement ce week-end."},{"temps":"23:35","texte":"Donc, on peut avoir plusieurs, plusieurs, plusieurs idées comme ça de contenu, en diversifiant nos piliers."},{"temps":"23:44","texte":"Et vous allez voir que, quand vous allez réfléchir, ou bien même utiliser ces stratégies-là, vous n''aurez plus de panne d''inspiration pour créer du contenu, parce que vous pouvez,"},{"temps":"23:56","texte":"par exemple, du lundi au vendredi, avoir au moins cinq publications qui ont le caractère éducatif, au moins cinq engageants, au moins cinq inspirants,"},{"temps":"24:07","texte":"au moins cinq promotionnels. Ça fait déjà une semaine remplie de publications."}]'::jsonb, 'srt', 'ENT_M08_C02_C-est-quoi-un-contenu-qui-attire.srt', now(),
  v.id, 'creer-du-contenu-qui-attire-les-clients-ch03-e3ae76', 'hls', 1451, 'ENT_M08_C02_C-est-quoi-un-contenu-qui-attire.mp4', 159087917, now(), true from v
