  returning id
)
insert into chapitres (module_id, position, libelle, titre, duree_minutes, script, script_format, script_nom_fichier, script_importe_le,
  video_id, video_cle, video_format, video_duree_secondes, video_nom_fichier, video_taille_octets, video_importee_le, sous_titres)
select 'mod-contenus-qui-attirent-des-clients', 7, 'Chapitre 7', 'Bonus : KPIs et publicité', 5, '[{"temps":"0:01","texte":"Maintenant, on va voir un petit bonus : les KPIs et la publicité."},{"temps":"0:07","texte":"Ce qu''on ne mesure pas, on ne peut pas l''améliorer."},{"temps":"0:11","texte":"Le KPI, en fait, qui veut dire key performance indicators, donc les indicateurs clés de performance, c''est ce qui va permettre de doubler ce qui fonctionne et d''arrêter ce qui ne fonctionne pas,"},{"temps":"0:22","texte":"bien sûr sans s''épuiser à tout maintenir dans le même cycle."},{"temps":"0:27","texte":"Quand on est sur les réseaux sociaux avec l''objectif qu''on s''est donné, on ne se disperse plus."},{"temps":"0:36","texte":"Un contenu, par exemple, peut générer peu de likes et pourtant être utile s''il obtient des messages, des enregistrements, des clics, des demandes de devis, des commandes et tout ça."},{"temps":"0:48","texte":"Donc, les indicateurs doivent correspondre à l''objectif que vous vous êtes fixé."},{"temps":"0:52","texte":"Si vous voulez vous faire connaître, vous devez regarder comme indicateurs la portée, les vues ou bien les nouveaux abonnés."},{"temps":"0:59","texte":"Si vous devez créer l''intérêt, vous devez regarder les enregistrements :"},{"temps":"1:03","texte":"est-ce que les gens enregistrent votre post ? Est-ce qu''ils partagent ?"},{"temps":"1:06","texte":"Ou bien, combien de temps ils restent à regarder votre contenu ?"},{"temps":"1:09","texte":"Si vous voulez avoir de la confiance, créer de la confiance, vous allez regarder les commentaires qualifiés, les réponses, les témoignages."},{"temps":"1:17","texte":"Pour générer des prospects, vous allez regarder : est-ce que vous avez des messages privés ? Est-ce que vous avez des clics sur WhatsApp ?"},{"temps":"1:22","texte":"Est-ce que les gens remplissent vos formulaires, ou bien remplissent les demandes de devis ? Etc."},{"temps":"1:28","texte":"Si vous voulez vendre, vous allez regarder :"},{"temps":"1:30","texte":"est-ce que vous avez des commandes ? Est-ce que vous avez des rendez-vous pour aujourd''hui, pour demain ?"},{"temps":"1:34","texte":"Est-ce que vous avez généré du chiffre d''affaires ?"},{"temps":"1:38","texte":"Donc, vous devez avoir ces éléments-là déjà établis."},{"temps":"1:43","texte":"Ça vous permettra de pouvoir naviguer avec un objectif, et de savoir comment atteindre cet objectif-là. Ça vous permet de ne pas naviguer à vue."},{"temps":"1:51","texte":"Maintenant, vous devez savoir que vous pouvez avoir le meilleur contenu sur les réseaux sociaux, mais s''il n''est vu par personne, il ne sert à rien."},{"temps":"2:01","texte":"Mais quand on parle de la publicité, il y a deux cas. Il y a le cas où, dès que vous lancez vos produits et services, par exemple, vous faites de la publicité."},{"temps":"2:10","texte":"Et il y a le cas où vous amplifiez ce qui marche déjà."},{"temps":"2:14","texte":"C''est-à-dire que faire de la publicité, ce n''est pas juste le fait de cliquer sur « Booster la publication »."},{"temps":"2:19","texte":"Si vous voulez booster un post, par exemple, vous devez prendre un post qui a déjà bien marché en termes de statistiques."},{"temps":"2:26","texte":"Vous allez voir s''il y a les likes, les commentaires, etc."},{"temps":"2:29","texte":"Et ensuite, vous allez définir l''objectif."},{"temps":"2:32","texte":"Maintenant, vous allez bien cibler dans les paramètres, et vous allez mettre un bon budget. S''il vous plaît, ne mettez pas un dollar, un euro, deux dollars, deux euros, s''il vous plaît."},{"temps":"2:42","texte":"Mettez au moins cinq. Et puis, testez d''abord avant de mettre en pause et tout ça."},{"temps":"2:47","texte":"La pub, elle amplifie ce qui marche, elle ne répare pas ce qui est cassé."},{"temps":"2:52","texte":"Donc, ce qui a déjà bien marché, c''est pour celui-là qu''on va chercher à définir un objectif, pour pouvoir cibler les personnes — on a dit les personas —, et on va mettre le budget qu''il faut."},{"temps":"3:02","texte":"Par la suite, on va voir si on atteint l''objectif ou pas."},{"temps":"3:05","texte":"Ça, c''est dans le cas où on cherche à améliorer ce qui existe déjà."},{"temps":"3:09","texte":"Mais si vous voulez lancer directement la publicité avec le produit, vous êtes en train de faire la publication avec le contenu promotionnel, et nous vous conseillons"},{"temps":"3:23","texte":"de faire la publicité en allant sur le gestionnaire de publicités."},{"temps":"3:26","texte":"Vous pouvez le faire sur les autres réseaux, vous pouvez le faire sur Business Suite, vous pouvez le faire sur l''application mobile et tout ça, mais pour avoir les meilleurs résultats, tout expert vous le dira : l''idéal,"},{"temps":"3:37","texte":"c''est de le faire via le gestionnaire de publicités."},{"temps":"3:40","texte":"Et vous allez voir que les résultats seront là, et vous allez obtenir ce que vous voulez en termes d''objectifs :"},{"temps":"3:46","texte":"si vous voulez des ventes, si vous voulez de la notoriété, si vous voulez plus de followers, etc., etc."},{"temps":"3:54","texte":"Maintenant, avant de publier, on a une checklist que je vous partage, que vous pouvez regarder. Vérifiez, avant de publier, ces choses : est-ce que mon accroche donne envie de continuer ?"},{"temps":"4:06","texte":"Est-ce que mon contenu est clair, simple et utile ? Est-ce que je parle à une audience précise ?"},{"temps":"4:12","texte":"Est-ce que je suscite une émotion ou une identification ?"},{"temps":"4:16","texte":"Est-ce que je montre une solution, ou une preuve, ou une expérience ?"},{"temps":"4:20","texte":"Est-ce que j''ai un seul appel à l''action, qui est clair ? Mon image, ma vidéo, c''est visible, c''est lisible ? Est-ce que c''est de qualité ?"},{"temps":"4:28","texte":"Est-ce que ce post correspond à un pilier et à un objectif ? Est-ce qu''enfin, je sais quel KPI je vais regarder ? Donc, vous pouvez regarder cette checklist-là."},{"temps":"4:37","texte":"Si tout est bon, tout est vert, allez-y, lancez-vous, analysez, regardez et améliorez. Donc, dernier exercice à faire :"},{"temps":"4:47","texte":"vous avez ces choses à remplir."},{"temps":"4:49","texte":"Quel est votre business ? Quel est votre réseau prioritaire ?"},{"temps":"4:52","texte":"Votre objectif ce mois où vous regardez cette vidéo : quel est votre objectif ?"},{"temps":"4:57","texte":"Qui est votre persona ? Sur quels piliers vous allez communiquer ?"},{"temps":"5:02","texte":"On a vu les quatre piliers. Qu''est-ce que vous avez communiqué sur les trois jours de la semaine, par exemple lundi, mercredi et vendredi ?"},{"temps":"5:09","texte":"Et quel est votre KPI à suivre ? Donc, vous allez travailler sur cet exercice-là, qui va vous permettre de pouvoir vous mettre dans le bain et vous habituer à pouvoir créer du contenu sans difficulté."},{"temps":"5:19","texte":"Parce que, si cela est maîtrisé, vous allez voir que votre manière de publier le contenu sera carrément différente."}]'::jsonb, 'srt', 'ENT_M08_C07_Bonus-KPIs-et-publicite.srt', now(),
  v.id, 'creer-du-contenu-qui-attire-les-clients-ch08-e53107', 'hls', 326, 'ENT_M08_C07_Bonus-KPIs-et-publicite.mp4', 30224183, now(), true from v
