insert into chapitres (module_id, position, libelle, titre, duree_minutes, script, script_format, script_nom_fichier, script_importe_le,
  video_id, video_cle, video_format, video_duree_secondes, video_nom_fichier, video_taille_octets, video_importee_le, sous_titres)
select 'mod-contenus-qui-attirent-des-clients', 8, 'Chapitre 8', 'Conclusion', 2, '[{"temps":"0:01","texte":"Ce qu''il faut retenir, c''est que le contenu qui attire les clients n''est pas celui qui parle le plus fort : c''est celui qui comprend le mieux son client et lui donne une raison claire de vous choisir."},{"temps":"0:15","texte":"Maintenant, voici ce que vous devez éviter, les erreurs fréquentes qu''on observe."},{"temps":"0:19","texte":"Évitez de parler uniquement de votre entreprise."},{"temps":"0:21","texte":"Évitez de vouloir toucher tout le monde."},{"temps":"0:24","texte":"Évitez de copier une tendance sans lien avec votre activité."},{"temps":"0:27","texte":"Évitez de publier sans objectif précis."},{"temps":"0:32","texte":"Vous allez voir la différence, et vous allez voir que, quand vous serez dans ce domaine-là, vous aurez à créer du contenu qui va changer les choses entre votre manière précédente de publier"},{"temps":"0:45","texte":"et votre nouvelle manière de publier. C''est celui qui comprend le mieux son client et lui donne une raison claire de choisir qui aura, à la fin, les meilleurs résultats. Publier, tester, analyser, et recommencer."},{"temps":"0:59","texte":"Merci pour votre attention, et n''oubliez pas les exercices, n''oubliez pas de réécouter à nouveau, et surtout de regarder ce qui est fait avant et après cette vidéo-là."},{"temps":"1:10","texte":"Quand vous allez l''appliquer, vous allez voir la différence :"},{"temps":"1:13","texte":"si vous respectez et que vous faites les analyses, vous verrez que vous ne serez plus en train de faire les mêmes choses qu''auparavant."},{"temps":"1:20","texte":"Merci à tous."}]'::jsonb, 'srt', 'ENT_M08_C08_Conclusion.srt', now(),
  v.id, 'creer-du-contenu-qui-attire-les-clients-ch09-6f721e', 'hls', 93, 'ENT_M08_C08_Conclusion.mp4', 12811708, now(), true from v
