-- ENT_M10 · Transformer TikTok en machine d’acquisition client
insert into modules (id, prix_fcfa, slug, numero, titre, programme, thematique_id, formateur_id, promesse, pourquoi, pour_qui, prerequis, acquis, livrable, faq, points_forts, duree_minutes, seo_mot_cle_principal, seo_title, seo_meta_description, statut, publie_le, pret_le)
values ('mod-transformer-tiktok-en-machine-dacquisition-client', 10000, 'transformer-tiktok-en-machine-dacquisition-client', 10, 'Transformer TikTok en machine d’acquisition client', 'entrepreneurs', 'th-ent-visibilite', 'for-soboro', 'Faites de votre compte TikTok une source régulière de clients : des contenus qui vendent, des lives structurés et des statistiques qui guident vos choix.', 'Des vues pour des vues ne servent à rien quand on vend un produit ou un service. Pour que TikTok amène des clients, il faut un objectif, des contenus qui poussent à agir, un moyen simple de vous contacter et de la régularité. Ce module vous montre comment construire votre tunnel de vente TikTok, structurer vos contenus et vos lives, et lire vos statistiques pour améliorer vos résultats.', array['Vous publiez sur TikTok, mais vos vues ne se transforment pas en ventes.', 'Vous voulez utiliser les lives pour vendre.', 'Vous ne savez pas lire les statistiques de vos vidéos.']::text[], 'Avoir un compte TikTok pour votre activité.', array['comprendre et construire votre tunnel de vente TikTok ;', 'bâtir vos contenus à partir de votre cible, en combinant trois types de contenus ;', 'fixer un rythme de publication tenable et organiser votre création ;', 'formuler des appels à l’action et animer un live qui vend ;', 'juger une vidéo sur sa capacité à vendre, notamment par la durée de visionnage.']::text[], 'Votre stratégie de contenu TikTok, avec votre cible, votre calendrier de publication et vos appels à l’action.', '[{"question":"Faut-il déjà avoir beaucoup d’abonnés sur TikTok ?","reponse":"Non. Le module explique comment gagner en visibilité puis transformer les vues en clients, quel que soit le nombre d’abonnés de départ."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, array[]::text[], 43, 'TikTok acquisition client', 'Transformer TikTok en machine d’acquisition client', 'Tunnel de vente, contenus, lives et statistiques : faites de TikTok une source de clients, avec Lyle Soboro. Module vidéo E-Masterclass Big Five.', 'disponible', '2026-10-20', '2026-10-20T15:02:20.294Z');
with v as (
  insert into videos (cle, nom, nom_fichier, taille_octets, duree_secondes, format)
  values ('transformer-tiktok-en-machine-dacquisition-client-ch01-85833a', 'Transformer TikTok en machine d’acquisition client · Introduction · Présentation du module', 'ENT_M10_C00_Intro.mp4', 41673042, 124, 'hls')
  returning id
)
insert into chapitres (module_id, position, libelle, titre, duree_minutes, script, script_format, script_nom_fichier, script_importe_le,
  video_id, video_cle, video_format, video_duree_secondes, video_nom_fichier, video_taille_octets, video_importee_le, sous_titres)
select 'mod-transformer-tiktok-en-machine-dacquisition-client', 0, 'Introduction', 'Présentation du module', 2, '[{"temps":"0:11","texte":"Bonjour à tous, je suis Lyle Soboro, expert marketing."},{"temps":"0:14","texte":"J''aide les entrepreneurs à gagner beaucoup d''argent dans leur business."},{"temps":"0:18","texte":"Donc là, on est dans le deuxième module de TikTok :"},{"temps":"0:22","texte":"comment est-ce qu''on transforme notre compte TikTok en machine à attirer facilement des clients et puis vendre à outrance ?"},{"temps":"0:32","texte":"Donc, dans ce module, on verra comment faire des contenus qui, en plus d''avoir de la visibilité, de susciter des interactions, peuvent nous ramener des clients. Donc, on verra comment est-ce qu''on fait."},{"temps":"0:44","texte":"On verra aussi comment est-ce qu''on utilise un peu les lives pour pouvoir avoir des clients, et puis aussi comment analyser les données statistiques de nos vidéos pour améliorer notre contenu"},{"temps":"0:54","texte":"et puis avoir plus de résultats. Donc, sans plus tarder, on va rentrer dans le vif du sujet. Je vais partager mon écran pour que vous voyiez la présentation, et puis on avance."},{"temps":"1:04","texte":"Transformer TikTok en machine d''acquisition client."},{"temps":"1:09","texte":"Donc, cette session-là durera maximum 60 minutes. Donc, on verra comme d''habitude des définitions. On verra certains éléments de lexique qui vous permettront de mieux comprendre et appréhender les modules,"},{"temps":"1:23","texte":"concepts et éléments pour pouvoir transformer votre compte TikTok en machine d''acquisition client. On verra aussi la stratégie de contenu que vous devez déployer pour pouvoir atteindre votre cible et puis vendre."},{"temps":"1:38","texte":"Et on verra comment est-ce qu''on lit les statistiques pour améliorer son contenu. Donc, la stratégie, elle est simple :"},{"temps":"1:49","texte":"il faut que vous ayez des objectifs, et puis vous structurez vos contenus pour attirer de la visibilité et la transformer en ventes."},{"temps":"1:58","texte":"On verra ce que c''est qu''un tunnel de vente TikTok, et puis on verra comment est-ce qu''on lit les statistiques."}]'::jsonb, 'srt', 'ENT_M10_C00_Intro.srt', now(),
  v.id, 'transformer-tiktok-en-machine-dacquisition-client-ch01-85833a', 'hls', 124, 'ENT_M10_C00_Intro.mp4', 41673042, now(), true from v
