insert into chapitres (module_id, position, libelle, titre, duree_minutes, script, script_format, script_nom_fichier, script_importe_le,
  video_id, video_cle, video_format, video_duree_secondes, video_nom_fichier, video_taille_octets, video_importee_le, sous_titres)
select 'mod-transformer-tiktok-en-machine-dacquisition-client', 2, 'Chapitre 2', 'Définitions', 3, '[{"temps":"0:01","texte":"Donc, tout d''abord, le premier terme qu''il faut que vous ayez en tête, c''est ce qu''on appelle l''appel à l''action. L''appel à l''action, c''est la dernière"},{"temps":"0:09","texte":"consigne que vous donnez au spectateur, celui qui va regarder votre vidéo, de faire. Donc, il a regardé votre vidéo, OK, mais qu''est-ce que vous lui demandez de faire ? Parce qu''il faudrait"},{"temps":"0:22","texte":"que vous voyiez les utilisateurs des réseaux comme des enfants, qui vont regarder et qui attendent qu''on leur dise de faire des choses."},{"temps":"0:29","texte":"Si vous ne leur dites pas de faire des choses, même s''ils savent bien qu''ils doivent le faire, ils ne vont pas vraiment passer à l''action. Ils vont plutôt aller"},{"temps":"0:34","texte":"regarder la prochaine vidéo, et puis ainsi de suite, ainsi de suite."},{"temps":"0:37","texte":"Quand vous faites vos contenus, il faut que vous puissiez leur donner une consigne. Ça peut être de vous contacter pour commander, ça peut être d''écrire quelque chose en commentaire,"},{"temps":"0:48","texte":"ça peut être de cliquer sur un lien, ça peut être de s''abonner."},{"temps":"0:51","texte":"Mais il faut que vous leur demandiez quelque chose à faire."},{"temps":"0:55","texte":"Deuxième terme qui est important, c''est ce qu''on appelle le tunnel de vente."},{"temps":"0:59","texte":"Le tunnel de vente, c''est un terme, je dirais, technique que les gens même utilisaient souvent pour se donner de la contenance."},{"temps":"1:09","texte":"Mais pour faire simple, c''est un peu le chemin par lequel va passer quelqu''un qui ne vous connaissait pas jusqu''au moment où il devient client en achetant votre produit. Par exemple, dans le cas de TikTok,"},{"temps":"1:19","texte":"c''est quelqu''un qui ne vous connaît pas : il défile, il tombe sur une de vos vidéos, il voit la vidéo, il est intéressé, il va suivre votre profil, il regarde d''autres vidéos. Et puis, il voit le lien de commande,"},{"temps":"1:30","texte":"il clique, il vient dans votre WhatsApp, vous discutez et vous concluez la vente."},{"temps":"1:35","texte":"Donc, ce parcours-là est appelé le tunnel de vente. Il faut qu''il soit clair, qu''il soit bien rodé, de sorte à ce que vous puissiez transformer vos vidéos, enfin, les vues de vos vidéos, en commandes."},{"temps":"1:50","texte":"Il y a les lives TikTok. Les lives TikTok, ce sont les diffusions en direct."},{"temps":"1:54","texte":"Donc, vous lancez la vidéo et, pendant que vous êtes en train de faire, les gens sont chez eux, sur le téléphone, et ils arrivent à vous suivre."},{"temps":"2:03","texte":"Donc, c''est une diffusion directe que vous pouvez utiliser pour faire beaucoup de choses : pour présenter vos produits, répondre aux questions, créer des interactions."},{"temps":"2:12","texte":"C''est assez efficace aujourd''hui pour pouvoir transformer votre profil en machine à avoir des clients."},{"temps":"2:21","texte":"Le dernier terme, c''est le taux de complétion."},{"temps":"2:23","texte":"Le taux de complétion, c''est le nombre de personnes qui regardent la vidéo, par rapport au nombre de personnes qui vont regarder et aller jusqu''au bout."},{"temps":"2:31","texte":"Si 100 personnes, combien de personnes ont regardé votre vidéo et sont allées jusqu''au bout ?"},{"temps":"2:35","texte":"On peut avoir des taux de complétion partiels, des taux :"},{"temps":"2:39","texte":"combien de personnes regardent 3 secondes, combien de personnes regardent 10, 20, 60 secondes, et ainsi de suite. Donc, le taux de complétion est une donnée qui permet de juger de l''efficacité de votre vidéo,"},{"temps":"2:50","texte":"juger de la capacité de votre vidéo à retenir l''attention des gens."},{"temps":"2:54","texte":"C''est quelque chose à surveiller, et c''est un très bon indicateur pour améliorer vos contenus et être beaucoup plus efficace."}]'::jsonb, 'srt', 'ENT_M10_C02_Definitions.srt', now(),
  v.id, 'transformer-tiktok-en-machine-dacquisition-client-ch03-b1fa13', 'hls', 181, 'ENT_M10_C02_Definitions.mp4', 32216775, now(), true from v
