update modules set slug = 'accroches-qui-stoppent-le-scroll-et-ia-copywriting',
  numero = 5,
  titre = 'Accroches qui stoppent le scroll & IA dans le copywriting',
  programme = 'social-media',
  thematique_id = 'th-sm-copywriting',
  formateur_id = 'for-othniel',
  promesse = 'Apprenez à construire plus rapidement des accroches capables de retenir l’attention, avec une méthode claire et l’IA comme assistant.',
  pourquoi = '<p><strong>Une publication</strong> peut être utile, bien conçue et correctement ciblée sans retenir l’attention si son ouverture manque d’impact. Ce module vous aide à structurer vos premiers mots, varier vos angles et produire plus rapidement sans déléguer votre réflexion à l’IA.</p>',
  pour_qui = array['Vous gérez les réseaux sociaux d’une marque ou de plusieurs clients.', 'Vos contenus peinent à retenir l’attention.', 'Vous souhaitez produire plus rapidement sans sacrifier la qualité.']::text[],
  prerequis = 'Aucun prérequis particulier. La méthode est expliquée et appliquée progressivement pendant le module.',
  acquis = array['comprendre le rôle d’une accroche et la distinguer du clickbait ;', 'appliquer la formule d’une accroche efficace et soigner la première ligne visible ;', 'rédiger vos prompts avec la méthode CRAFT et itérer avec l’IA ;', 'connaître les limites de l’IA et réécrire ses propositions ;', 'choisir les indicateurs à suivre selon votre objectif.']::text[],
  livrable = 'Vos propres accroches adaptées à votre secteur, travaillées dans les deux exercices du module, et une méthode de prompt réutilisable avec l’IA.',
  faq = '[{"question":"Ai-je besoin d’un outil d’IA payant ?","reponse":"Non. Le module ne dépend pas d’un outil payant particulier. Les fonctionnalités nécessaires et les différentes options sont présentées pendant le module."},{"question":"La méthode peut-elle s’appliquer à tous les secteurs ?","reponse":"Oui. Les principes enseignés sont adaptables à différents secteurs. Les exercices vous permettent de travailler directement à partir de votre activité, de votre marque ou de vos clients."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb,
  points_forts = array[]::text[],
  duree_minutes = 55,
  seo_mot_cle_principal = 'accroches réseaux sociaux',
  seo_title = 'Accroches qui stoppent le scroll & IA dans le copywriting',
  seo_meta_description = 'Écrivez des accroches qui retiennent l’attention et utilisez l’IA sans perdre votre ton, avec Coury Othniel. Module vidéo E-Masterclass Big Five.',
  statut = 'disponible',
  publie_le = '2026-10-20',
